static const RuleHelpRow *findRow(const std::string &code)
{
	for(size_t i = 0; i < sizeof(HELP) / sizeof(HELP[0]); i++) if(code == HELP[i].code) return &HELP[i];
	return nullptr;
}

int RuleHelpCount() { return (int)(sizeof(HELP) / sizeof(HELP[0])); }
bool RuleHelpAt(int i, std::string &code, std::string &what, std::string &risk, std::string &fix)
{
	if(i < 0 || i >= RuleHelpCount()) return false;
	code = HELP[i].code; what = T(HELP[i].what); risk = T(HELP[i].risk); fix = T(HELP[i].fix);
	return true;
}

bool RuleHelp(const std::string &code, std::string &what, std::string &risk, std::string &fix)
{
	const RuleHelpRow *r = findRow(code);
	if(!r && code.size() > 1 && code[code.size() - 1] >= 'a' && code[code.size() - 1] <= 'z') r = findRow(code.substr(0, code.size() - 1));
	if(!r){ size_t d = code.find('-'); if(d != std::string::npos) r = findRow(code.substr(0, d)); }
	if(!r) return false;
	what = T(r->what); risk = T(r->risk); fix = T(r->fix);
	return true;
}

